using System;using System.Linq;using UnityEngine;using UnityEditor;
namespace LWS.TruckSports.Editor {
public static class SportsRallyAuthoring {
 public static SportsRallyViews Views(SportsEventSession m,SportsEventTruck[] trucks){var v=m.gameObject.AddComponent<SportsRallyViews>();v.session=m;v.trucks=trucks;v.broadcast=SportsEventAuthoring.Camera(m.Title+" broadcast");v.broadcast.Pose(trucks[0].transform.position+Vector3.forward*8,new Vector3(0,16,-24),68,true);v.broadcast.view.farClipPlane=2100;v.views=new SportsEventCamera[4];for(int i=0;i<4;i++){v.views[i]=SportsEventAuthoring.Camera(m.Title+" chase "+i);v.views[i].view.enabled=false;v.views[i].view.farClipPlane=2100;}foreach(var c in v.views)TuneCamera(c);TuneCamera(v.broadcast);m.cameras=new[]{v.broadcast.view};return v;}
 public static void TuneCamera(SportsEventCamera camera){camera.follow.m_XDamping=camera.follow.m_ZDamping=.25f;camera.follow.m_YDamping=.20f;var composer=camera.rig.GetCinemachineComponent<Cinemachine.CinemachineComposer>();composer.m_HorizontalDamping=composer.m_VerticalDamping=.1f;composer.m_DeadZoneWidth=composer.m_DeadZoneHeight=.04f;var collision=camera.rig.GetComponent<Cinemachine.CinemachineCollider>()??camera.rig.gameObject.AddComponent<Cinemachine.CinemachineCollider>();collision.m_CollideAgainst=1;collision.m_CameraRadius=.35f;collision.m_MinimumDistanceFromTarget=2;collision.m_Damping=.2f;}
 public static SportsMotionReplay Replay(SportsEventSession m,Transform[] sources){var replay=m.gameObject.AddComponent<SportsMotionReplay>();replay.sources=sources;replay.ghosts=new Transform[sources.Length];for(int i=0;i<sources.Length;i++){var g=UnityEngine.Object.Instantiate(sources[i].gameObject);g.name="Recorded render-only "+i;g.transform.SetParent(null);foreach(var j in g.GetComponentsInChildren<Joint>(true))UnityEngine.Object.DestroyImmediate(j);foreach(var t in g.GetComponentsInChildren<Transform>(true)){t.gameObject.layer=0;foreach(var c in t.GetComponents<Component>())if(!(c is Transform)&&!(c is Renderer)&&!(c is MeshFilter))UnityEngine.Object.DestroyImmediate(c);}replay.ghosts[i]=g.transform;g.SetActive(false);}return replay;}
 public static void CompactUI(SportsEventSession m){var menu=m.menus;var header=menu.header.transform.parent.GetComponent<RectTransform>();header.anchoredPosition=new Vector2(0,512);header.sizeDelta=new Vector2(1880,44);menu.header.rectTransform.sizeDelta=new Vector2(1800,38);menu.header.fontSizeMax=23;menu.standings.rectTransform.anchoredPosition=new Vector2(-745,305);menu.standings.rectTransform.sizeDelta=new Vector2(405,500);menu.standings.fontSizeMax=21;menu.standings.fontSizeMin=17;menu.status.rectTransform.anchoredPosition=new Vector2(0,-505);menu.status.fontSizeMax=22;for(int i=0;i<4;i++){menu.viewTexts[i].rectTransform.sizeDelta=new Vector2(790,110);menu.viewTexts[i].fontSizeMax=22;menu.viewTexts[i].fontSizeMin=18;menu.viewTexts[i].transform.parent.Find("View data backing").GetComponent<RectTransform>().sizeDelta=new Vector2(810,130);}}
 public static void FitTruck(SportsEventTruck truck){var binding=truck.gameObject.AddComponent<SportsWheelMeshBinding>();binding.truck=truck;binding.meshes=new Transform[4];binding.centers=new Vector3[4];binding.alignment=new Quaternion[4];string[] names={"Whl HD FL","Whl HD FR","Whl HD RL","Whl HD RR"};for(int i=0;i<4;i++){var f=truck.visuals.GetComponentsInChildren<MeshFilter>(true).First(x=>x.name==names[i]);var b=BoundsIn(f,truck.transform);f.transform.localScale*=truck.wheels[i].wheel.radius/Mathf.Max(.01f,b.extents.y);binding.meshes[i]=f.transform;binding.centers[i]=f.sharedMesh.bounds.center;binding.alignment[i]=Quaternion.Inverse(truck.wheels[i].wheel.rotatingContainer.rotation)*f.transform.rotation;}bool first=true;Bounds bounds=default;foreach(var f in truck.visuals.GetComponentsInChildren<MeshFilter>(true)){var b=BoundsIn(f,truck.transform);if(first){bounds=b;first=false;}else bounds.Encapsulate(b);}truck.shape.center=bounds.center;truck.shape.size=bounds.size;}
 public static Bounds BoundsIn(MeshFilter f,Transform root){var b=f.sharedMesh.bounds;Bounds result=default;for(int i=0;i<8;i++){var p=root.InverseTransformPoint(f.transform.TransformPoint(b.center+Vector3.Scale(b.extents,new Vector3((i&1)==0?-1:1,(i&2)==0?-1:1,(i&4)==0?-1:1))));if(i==0)result=new Bounds(p,Vector3.zero);else result.Encapsulate(p);}return result;}
 public static void Prop(Transform parent,string source,Vector3 position,Vector3 size){var root=new GameObject("Installed course prop").transform;root.SetParent(parent,false);root.localPosition=position;LWS.TruckKeepaway.Editor.KeepawayPresentationAuthoring.Fit(root,source,size,0);}
}
}
